<?php require_once '../config/auth.php';require_login();header('Content-Type: application/json');
try{ $cart=json_decode($_POST['cart']??'[]',true);$paid=(float)($_POST['paid']??0);$payment=$_POST['payment']??'Tunai';if(!is_array($cart)||!count($cart))throw new Exception('Keranjang kosong');if(!in_array($payment,['Tunai','QRIS','Debit'],true))$payment='Tunai';$pdo->beginTransaction();$total=0;$items=[];$lock=$pdo->prepare('SELECT id,name,price,stock FROM products WHERE id=? FOR UPDATE');foreach($cart as $i){$lock->execute([(int)$i['id']]);$p=$lock->fetch();if(!$p||$i['qty']<1||$i['qty']>$p['stock'])throw new Exception('Stok '.$i['name'].' tidak mencukupi');$qty=(int)$i['qty'];$subtotal=$p['price']*$qty;$total+=$subtotal;$items[]=[$p,$qty,$subtotal];}$change=$paid-$total;if($payment==='Tunai'&&$change<0)throw new Exception('Nominal pembayaran kurang');if($payment!=='Tunai'){$paid=$total;$change=0;}$invoice='TRX'.date('ymdHis').rand(10,99);$ins=$pdo->prepare('INSERT INTO sales(invoice_no,user_id,total,paid,change_amount,payment_method) VALUES(?,?,?,?,?,?)');$ins->execute([$invoice,current_user()['id'],$total,$paid,$change,$payment]);$saleId=(int)$pdo->lastInsertId();$ii=$pdo->prepare('INSERT INTO sale_items(sale_id,product_id,qty,price,subtotal) VALUES(?,?,?,?,?)');$up=$pdo->prepare('UPDATE products SET stock=stock-? WHERE id=?');foreach($items as [$p,$qty,$subtotal]){$ii->execute([$saleId,$p['id'],$qty,$p['price'],$subtotal]);$up->execute([$qty,$p['id']]);}$pdo->commit();echo json_encode(['success'=>true,'invoice'=>$invoice]);}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();echo json_encode(['success'=>false,'message'=>$e->getMessage()]);}
